import {esc,icon} from './ui.mjs';
import {ensureAigcStyle} from './aigc-detection.mjs';
import {createDetectionProgress,ensureDetectionProgressStyle} from './detection-progress.mjs';
import {createDetectionWorkflow} from './detection-workflow.mjs';
import {detectionPriceText,detectionPriceSnapshot} from './detection-billing.mjs';
import {validatePaperUpload} from './paper-upload-policy.mjs';
import {importWorkspaceDocument} from './document-import.mjs';
import {createDocumentServiceClient,watchDocumentService} from './document-services-client.mjs';
export function mountCombinedDetection({container,fetchImpl,importDocument=importWorkspaceDocument,pollInterval=2200}={}){
 const doc=container.ownerDocument,win=doc.defaultView,$=s=>container.querySelector(s);let alive=true,owner=null,cap={},text='',title='',item=null,busy=false,timer=null,intent=null,workflow,progress,unwatch=()=>{};
 const current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});ensureAigcStyle(doc);ensureDetectionProgressStyle(doc);
 const status=message=>{if(current())$('[data-joint-status]').textContent=message;};
 const stop=()=>{win.clearTimeout(timer);timer=null;};
 const controls=()=>{if(!current())return;const active=item?.status==='running';$('[data-joint-file]').disabled=busy||active;$('[data-joint-start]').disabled=busy||active||!text;$('[data-joint-cancel]').hidden=!active;$('[data-joint-cancel]').disabled=busy;};
 async function checkOwner(){const me=await client.request('/auth/me');if(me.user?.id!==owner){text='';title='';item=null;intent=null;stop();progress?.dispose();container.innerHTML='<p role="alert">登录账户已变化，请重新进入联合检测。</p>';alive=false;throw Error('登录账户已变化，请重新进入本功能。');}}
 function render(){controls();if(!item)return;const active=item.status==='running';workflow.update({phase:active?'running':item.status==='completed'?'complete':'failed',hasText:!!text,valid:!!text,hasTask:true,hasReport:item.status==='completed'});
  if(active){progress.update({state:'running',startedAt:item.createdAt});stop();timer=win.setTimeout(()=>void run(()=>read(item.id)),pollInterval);return;}
  progress.dispose();$('[data-joint-result]').innerHTML=`<section class="aigc-detection-card"><h3>${item.status==='completed'?'两份检测报告已完成':'本次联合检测未完成'}</h3>${item.error?`<p>${esc(item.error)}</p>`:''}<div class="actions">${item.children.filter(c=>c.status==='completed').map(c=>`<a class="btn secondary" href="#category/detection?view=${c.kind==='aigc'?'ai':'web'}&report=${encodeURIComponent(c.id)}">查看${c.kind==='aigc'?' AI 率':'重复率'}报告 →</a>`).join('')}</div></section>`;
 }
 async function read(id){await checkOwner();const next=await client.request('/combined-detections/'+encodeURIComponent(id));await checkOwner();item=next;render();}
 async function run(fn){if(busy||!current())return;busy=true;controls();try{await fn();}catch(e){if(current()){status(e.message||'暂时无法读取，请稍后重试。');if(!item){if(e.status>=400&&e.status<500){intent=null;progress?.clear();workflow?.update({phase:'review',hasText:!!text,valid:!!text});}else progress?.update({state:'recovering'});}}}finally{busy=false;controls();if(current()&&item?.status==='running'&&!timer)timer=win.setTimeout(()=>void run(()=>read(item.id)),pollInterval);}}
 async function submit(){await checkOwner();intent??={text,title,expectedUserId:owner,idempotencyKey:crypto.randomUUID(),...detectionPriceSnapshot(cap)};progress.update({state:'submitting'});$('[data-joint-result]').replaceChildren();workflow.update({phase:'submitting',hasText:true,valid:true,hasTask:true});status('正在提交联合检测…');item=await client.request('/combined-detections',intent);intent=null;await checkOwner();render();}
 const ready=(async()=>{container.innerHTML='<p role="status">正在读取联合检测服务…</p>';try{const [me,caps]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);if(!current())return;owner=me.user?.id;cap=caps.combinedDetection||{};if(!owner||!cap.ready){container.innerHTML='<section class="aigc-detection-card"><h2>联合检测暂不可用</h2><p>请登录后重试，或使用单项检测。</p></section>';return;}
 container.innerHTML=`<div data-joint-workflow></div><section class="aigc-detection-card aigc-detection-main"><header class="aigc-detection-head"><span>${icon('shield',25)}</span><div><h2>一次上传，获得两份检测报告</h2><p>同一篇论文分别检测重复率和 AI 率，独立标注原文与修改位置。</p></div></header><label class="aigc-paper-upload"><span>${icon('upload',28)}</span><strong data-joint-name>上传 DOCX 原文</strong><span>单篇不超过 20,000 字符</span><span class="aigc-upload-button">选择文件</span><input type="file" accept=".docx" data-joint-file data-upload-presentation="off" aria-label="上传联合检测原文"></label><p data-joint-status role="status" aria-live="polite">上传后即可开始检测。</p><div class="aigc-submit-bar"><div><p class="detection-submit-price">${esc(detectionPriceText(cap))}</p><small>联合检测一次计费；单项套餐次数请在对应检测中使用。失败或取消释放本次预占。</small></div><button class="btn primary" data-joint-start disabled>开始联合检测</button><button class="btn secondary" data-joint-cancel hidden>取消检测</button></div><div data-joint-progress hidden></div><div data-joint-result></div></section>`;
 workflow=createDetectionWorkflow($('[data-joint-workflow]'),{kind:'combined'});progress=createDetectionProgress($('[data-joint-progress]'));workflow.update();
 $('[data-joint-file]').onchange=()=>{const file=$('[data-joint-file]').files?.[0];$('[data-joint-file]').value='';if(!file)return;void run(async()=>{validatePaperUpload(file);await checkOwner();status('正在读取论文…');const result=await importDocument(file,$('[data-joint-status]'));await checkOwner();if(Array.from(result.text||'').length>20000||(result.text||'').trim().length<50)throw Error('请上传含 50～20,000 字符正文的 DOCX。');text=result.text;title=file.name.replace(/\.docx$/i,'').slice(0,200);item=null;intent=null;$('[data-joint-name]').textContent=file.name;status('原文已就绪，点击开始联合检测即可。');workflow.update({phase:'review',hasText:true,valid:true});});};
 $('[data-joint-start]').onclick=()=>void run(submit);$('[data-joint-cancel]').onclick=()=>void run(async()=>{await checkOwner();item=await client.request('/combined-detections/'+item.id+'/cancel',{expectedUserId:owner});render();});
 const recent=await client.request('/combined-detections');if(current()&&recent.items?.[0]){item=recent.items[0];render();}
 }catch(e){if(current())container.innerHTML=`<p role="alert">${esc(e.message||'服务暂不可用')}</p>`;}})();
 function dispose(){if(!alive)return;alive=false;stop();progress?.dispose();workflow?.dispose();client.dispose();unwatch();}unwatch=watchDocumentService(container,dispose);return{ready,dispose,canLeave:()=>!busy};
}
